using System.IO;
using UnityEditor;
using UnityEditor.Build.Reporting;
using UnityEngine;

// Step 14: one-click Android APK build, from the Editor menu or command line:
// Unity -batchmode -quit -projectPath <path> -executeMethod BuildScript.BuildAndroid
// Builds Home (0) + Dungeon (1); scenes are generated by SceneSetup first.
public static class BuildScript
{
    static string GetArg(string name)
    {
        string[] args = System.Environment.GetCommandLineArgs();
        for (int i = 0; i + 1 < args.Length; i++)
            if (args[i] == name) return args[i + 1];
        return null;
    }

    [MenuItem("Build/Android APK (Dungeon Master)")]
    public static void BuildAndroid()
    {
        SceneSetup.EnsureScenes();
        // Optional CI versioning: -apkVersion 1.0.47 -apkVersionCode 47.
        // Without them (local builds), keep the default name and settings.
        string apkName = "DungeonMaster.apk";
        string apkVersion = GetArg("-apkVersion");
        if (!string.IsNullOrEmpty(apkVersion))
        {
            PlayerSettings.bundleVersion = apkVersion;
            apkName = "DungeonMaster-v" + apkVersion + ".apk";
        }
        if (int.TryParse(GetArg("-apkVersionCode"), out int apkVersionCode))
            PlayerSettings.Android.bundleVersionCode = apkVersionCode;
        // Absolute output dir under the project root; the CI runner's working
        // directory is not guaranteed to be the project folder.
        string buildsDir = Path.Combine(Directory.GetParent(Application.dataPath).FullName, "Builds");
        Directory.CreateDirectory(buildsDir);
        var options = new BuildPlayerOptions
        {
            scenes = new[] { SceneSetup.HomeScenePath, SceneSetup.DungeonScenePath },
            locationPathName = Path.Combine(buildsDir, apkName),
            target = BuildTarget.Android,
            options = BuildOptions.None,
        };
        BuildReport report = BuildPipeline.BuildPlayer(options);
        Debug.Log($"Android build: {report.summary.result} in {report.summary.totalTime.TotalSeconds:F1}s, " +
                  $"size {report.summary.totalSize} bytes.");
        if (report.summary.result != BuildResult.Succeeded)
            throw new System.Exception("Android build failed. See Console for errors.");
    }
}
